package net.civeira.phylax.features.access.trustedclient.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class BackChannelLogoutSessionRequiredVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property back channel logout session required of trusted client ")
  void test_back_channel_logout_session_required_v_o_builder() {
    Assertions.assertFalse(
        BackChannelLogoutSessionRequiredVO.nullValue().isBackChannelLogoutSessionRequired(),
        "A empty vo should have a null value");
    Assertions.assertFalse(
        BackChannelLogoutSessionRequiredVO.tryFrom(null).isBackChannelLogoutSessionRequired(),
        "With a null value, no present result");
    Assertions.assertEquals(true,
        BackChannelLogoutSessionRequiredVO.from(true).isBackChannelLogoutSessionRequired());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> BackChannelLogoutSessionRequiredVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + true + "]",
        BackChannelLogoutSessionRequiredVO.from(true).toString());
  }
}
